            {/* Progress bar */}
            <div className="relative h-1.5 w-full rounded-full overflow-hidden bg-gray-200/20">
              <div className="absolute top-0 left-0 h-full rounded-full bg-gradient-to-r from-green-400 to-emerald-500 animate-[shrinkWidth_3s_linear_forwards]"></div>
            </div>
          </div>
        </div>
      )}

    </div>
  </div>
);
};

export default Subscriptions;
